8	  return liveCells.filter(
9	    (other) => other !== cell && isNeighbor(cell, other)
10	  ).length;
11	}
12	
13	export function nextGeneration(liveCells: Cell[]): Cell[] {
14	  return liveCells.filter((cell) => countNeighbors(cell, liveCells) === 2);
